package org.casbin.jcasbin.effect;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import org.junit.runners.Parameterized.Parameters;

import java.util.Arrays;
import java.util.Collection;

import static org.junit.Assert.*;

@RunWith(Parameterized.class)
public class PushTests {
    private DefaultStreamEffector effector;
    private final String expr;
    private final Effect inputEffect;
    private final int currentIndex;
    private final int policySize;
    private final boolean expectedDone;
    private final boolean expectedEffect;
    private final int expectedExplainIndex;

    public PushTests(String expr, Effect inputEffect, int currentIndex, int policySize,
                     boolean expectedDone, boolean expectedEffect, int expectedExplainIndex) {
        this.expr = expr;
        this.inputEffect = inputEffect;
        this.currentIndex = currentIndex;
        this.policySize = policySize;
        this.expectedDone = expectedDone;
        this.expectedEffect = expectedEffect;
        this.expectedExplainIndex = expectedExplainIndex;
    }

    @Parameters(name = "{index}: expr={0}, effect={1}, index={2}, size={3}")
    public static Collection<Object[]> data() {
        return Arrays.asList(new Object[][]{
            // some(where (p_eft == allow))
            {"some(where (p_eft == allow))", Effect.Allow, 0, 5, true, true, 0},
            {"some(where (p_eft == allow))", Effect.Deny, 1, 5, false, false, -1},
            {"some(where (p_eft == allow))", Effect.Indeterminate, 2, 5, false, false, -1},

            // !some(where (p_eft == deny))
            {"!some(where (p_eft == deny))", Effect.Allow, 0, 5, false, true, -1},
            {"!some(where (p_eft == deny))", Effect.Deny, 1, 5, true, false, 1},
            {"!some(where (p_eft == deny))", Effect.Indeterminate, 2, 5, false, true, -1},

            // some(where (p_eft == allow)) && !some(where (p_eft == deny))
            {"some(where (p_eft == allow)) && !some(where (p_eft == deny))", Effect.Allow, 0, 5, false, true, 0},
            {"some(where (p_eft == allow)) && !some(where (p_eft == deny))", Effect.Allow, 2, 5, false, true, 0},
            {"some(where (p_eft == allow)) && !some(where (p_eft == deny))", Effect.Deny, 1, 5, true, false, 1},
            {"some(where (p_eft == allow)) && !some(where (p_eft == deny))", Effect.Indeterminate, 3, 5, false, false, -1},

            // priority(p_eft) || deny
            {"priority(p_eft) || deny", Effect.Allow, 0, 5, true, true, 0},
            {"priority(p_eft) || deny", Effect.Deny, 1, 5, true, false, 1},
            {"priority(p_eft) || deny", Effect.Indeterminate, 2, 5, false, false, -1},

            // subjectPriority(p_eft) || deny
            {"subjectPriority(p_eft) || deny", Effect.Allow, 0, 5, true, true, 0},
            {"subjectPriority(p_eft) || deny", Effect.Deny, 1, 5, true, false, 1},
            {"subjectPriority(p_eft) || deny", Effect.Indeterminate, 2, 5, false, false, -1}
        });
    }

    @Before
    public void setUp() {
        effector = new DefaultStreamEffector(expr);
    }

    @Test
    public void testPush() {
        boolean result = effector.push(inputEffect, currentIndex, policySize);

        assertEquals(expectedDone, result);
        assertEquals(expectedEffect, effector.getEffect());
        assertEquals(expectedExplainIndex, effector.getExplainIndex());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testUnsupportedExpression() {
        DefaultStreamEffector invalidEffector = new DefaultStreamEffector("invalid expression");
        invalidEffector.push(Effect.Allow, 0, 5);
    }

    @Test
    public void testMultiplePushes() {
        // Test multiple pushes for expressions that don't set done immediately
        DefaultStreamEffector multiEffector = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");

        // First push with Allow
        boolean result1 = multiEffector.push(Effect.Allow, 0, 5);
        assertFalse(result1);
        assertTrue(multiEffector.getEffect());
        assertEquals(0, multiEffector.getExplainIndex());

        // Second push with Deny
        boolean result2 = multiEffector.push(Effect.Deny, 1, 5);
        assertTrue(result2);
        assertFalse(multiEffector.getEffect());
        assertEquals(1, multiEffector.getExplainIndex());
    }

    @Test
    public void testResetState() {
        // Test that effector maintains state across pushes
        DefaultStreamEffector stateEffector = new DefaultStreamEffector("some(where (p_eft == allow))");

        // First push with Deny (should not set done)
        boolean result1 = stateEffector.push(Effect.Deny, 0, 5);
        assertFalse(result1);
        assertFalse(stateEffector.getEffect());
        assertEquals(-1, stateEffector.getExplainIndex());

        // Second push with Allow (should set done)
        boolean result2 = stateEffector.push(Effect.Allow, 1, 5);
        assertTrue(result2);
        assertTrue(stateEffector.getEffect());
        assertEquals(1, stateEffector.getExplainIndex());
    }
}

